/**
 * Criticality. Betweenness plus articulation points, with the "why is this
 * critical?" explanation generated by the backend from computed statistics.
 */
import { useState } from "react";
import { Crosshair, Play } from "lucide-react";
import NetworkCanvas from "@/components/NetworkCanvas";
import {
  Chip, Empty, Metric, Note, Panel, fmt, riskColor, riskLabel,
} from "@/components/ui";

export default function CriticalitySection({ p, selected, onSelect }: any) {
  const { state } = p;
  const [topPct, setTopPct] = useState(10);
  const node = state.crit?.top_nodes?.find((n: any) => n.node === selected)
            ?? state.crit?.top_nodes?.[0];

  return (
    <div className="flex-1 grid grid-cols-12 gap-3 min-h-0">
      <Panel className="col-span-12 lg:col-span-8" title="Criticality heatmap"
        actions={<div className="flex gap-1.5">
          {(["LOW","MEDIUM","HIGH","CRITICAL"] as const).map((l, i) => (
            <span key={l} className="flex items-center gap-1 text-[10px] text-ink-500">
              <span className="w-2 h-2 rounded-sm"
                    style={{ background: riskColor([0.1,0.35,0.6,0.85][i]) }} />
              {l}
            </span>
          ))}
        </div>}>
        {state.graph ? (
          <NetworkCanvas className="w-full h-full min-h-[440px]"
            geojson={state.graph.geojson} scores={state.crit?.scores}
            gatekeepers={state.crit?.gatekeepers} selected={selected}
            onSelectNode={onSelect} />
        ) : <Empty icon={Crosshair} title="Build the graph first" />}
      </Panel>

      <div className="col-span-12 lg:col-span-4 flex flex-col gap-3 overflow-auto">
        <Panel title="Analysis" dense>
          <div className="space-y-3">
            <div>
              <div className="flex justify-between text-[11px] mb-1">
                <span className="text-ink-300">Highlight top</span>
                <span className="metric">{topPct}%</span>
              </div>
              <input type="range" min={1} max={50} value={topPct}
                     onChange={(e) => setTopPct(+e.target.value)}
                     className="w-full accent-accent" />
            </div>
            <button className="btn-primary w-full justify-center"
                    disabled={!state.graph || !!state.busy}
                    onClick={() => p.criticality(topPct)}>
              <Play size={14} /> Compute centrality
            </button>
            {state.crit && !state.crit.exact && (
              <Note tone="warn">
                Betweenness <strong>estimated</strong> from {state.crit.pivots} pivots:
                exact Brandes is O(V&middot;E) and too slow for this graph size.
                Values are unbiased estimates, not exact.
              </Note>
            )}
            {state.crit?.exact && (
              <Note>Exact Brandes betweenness, weighted by {state.crit.weight}.</Note>
            )}
          </div>
        </Panel>

        {state.crit && (
          <>
            <Panel title="Top critical intersections" dense>
              <div className="space-y-1 max-h-56 overflow-auto">
                {state.crit.top_nodes.map((n: any) => (
                  <button key={n.node} onClick={() => onSelect(n.node)}
                    className={`w-full flex items-center gap-2 px-2 py-1.5 rounded text-[11px]
                      transition-colors ${selected === n.node
                        ? "bg-accent/10 border border-accent/30" : "hover:bg-base-700 border border-transparent"}`}>
                    <span className="w-2 h-2 rounded-full shrink-0"
                          style={{ background: riskColor(n.criticality) }} />
                    <span className="font-mono">#{n.node}</span>
                    <span className="text-ink-500">bc {n.betweenness.toFixed(3)}</span>
                    {n.is_gatekeeper && <span className="ml-auto text-[9px] text-accent">GATEKEEPER</span>}
                  </button>
                ))}
              </div>
            </Panel>

            {node && (
              <Panel title={`Why is #${node.node} critical?`} dense>
                <div className="space-y-3">
                  <div className="grid grid-cols-2 gap-3">
                    <Metric size="sm" label="Criticality" value={node.criticality.toFixed(3)}
                            tone={node.criticality > 0.6 ? "bad" : "warn"} />
                    <Metric size="sm" label="Betweenness" value={node.betweenness.toFixed(4)} />
                    <Metric size="sm" label="Degree" value={node.degree} />
                    <Metric size="sm" label="Incident length"
                            value={fmt.km(node.incident_length_m)} unit="km" />
                    {node.od_pairs_affected_pct != null && (
                      <Metric size="sm" label="OD pairs affected"
                              value={`${node.od_pairs_affected_pct.toFixed(1)}%`} tone="bad" />
                    )}
                    {node.efficiency_loss_pct != null && (
                      <Metric size="sm" label="Efficiency loss"
                              value={`${node.efficiency_loss_pct.toFixed(1)}%`} tone="bad" />
                    )}
                  </div>
                  <div className="flex gap-1.5">
                    <Chip tone={node.criticality > 0.6 ? "bad" : "warn"}>
                      {riskLabel(node.criticality)}
                    </Chip>
                    {node.is_gatekeeper && <Chip tone="accent">Gatekeeper</Chip>}
                  </div>
                  <p className="text-[11px] text-ink-300 leading-relaxed">{node.explanation}</p>
                  <Note>
                    Every figure above is computed from the routable graph. Nothing
                    here is templated commentary.
                  </Note>
                </div>
              </Panel>
            )}

            <Panel title="Structural single points of failure" dense>
              <div className="grid grid-cols-2 gap-3">
                <Metric size="sm" label="Gatekeeper nodes" value={state.crit.gatekeepers.length}
                        tone={state.crit.gatekeepers.length ? "warn" : "good"} />
                <Metric size="sm" label="Bridge edges" value={state.crit.bridge_edges.length}
                        tone={state.crit.bridge_edges.length ? "warn" : "good"} />
              </div>
              <div className="mt-3">
                <Note>
                  A high-betweenness node is merely <em>busy</em> and usually has
                  alternatives. A gatekeeper has none: removing it disconnects part
                  of the network outright. The two rarely coincide.
                </Note>
              </div>
            </Panel>
          </>
        )}
      </div>
    </div>
  );
}
